private destroyRef = inject(DestroyRef);

ngOnInit(): void {
  this.filtroService.filtro$
    .pipe(takeUntilDestroyed(this.destroyRef))
    .subscribe(filtro => {
      console.log('Documentos filtrando: ' + filtro);
    });
}
